from pathlib import Path
import re
s=Path('review/02-ia-v50.html').read_text(encoding='utf-8').replace('v50','v51')
needle="if(/성령으로 인하여|동정 마리아에게서 육신|사람이 되셨/.test(p.textContent))p.className+=' reader__bow-phrase';speechBody.append(p);"
assert needle in s
s=s.replace(needle,"""if(/성령으로 인하여|동정 마리아에게서 육신|사람이 되셨/.test(p.textContent))p.className+=' reader__bow-phrase';const blessing=p.textContent.match(/성부와\\s*\\+\\s*성자와\\s*성령/);if(blessing){const full=p.textContent;const before=document.createElement('span');before.textContent=full.slice(0,blessing.index);const marked=document.createElement('span');marked.className='reader__bow-phrase';marked.textContent=blessing[0];const after=document.createElement('span');after.textContent=full.slice(blessing.index+blessing[0].length);p.textContent='';p.append(before,marked,after);}speechBody.append(p);""")
s=s.replace(" decorateLiturgy(node);", """ decorateLiturgy(node);
 if(block.item?.title==='강복'){const priest=Array.from(node.querySelectorAll('.reader__speech-card--priest')).find(card=>card.textContent.includes('성부와'));const guide=Array.from(node.querySelectorAll('.reader__guidance')).find(p=>p.textContent.includes('성호를 긋는다'));const body=priest?.querySelector('.reader__speech-body');if(body&&guide)body.append(guide);}""",1)
Path('review/02-ia-v51.html').write_text(s,encoding='utf-8',newline='\r\n');Path('work/review-ia-v51-check.js').write_text(re.search(r'<script>([\s\S]*?)</script>',s)[1],encoding='utf-8')
t=Path('work/test-reader-v50.cjs').read_text(encoding='utf-8').replace('02-ia-v50.html','02-ia-v51.html');t+='''\nmode.value='beginner';const b51=run("renderBlock(flowBlocks(3).find(b=>b.item?.title==='강복'))");const priest51=roles(b51).find(n=>n.attrs['data-speech-role']==='priest'&&n.textContent.includes('성부와'));assert.ok(priest51.textContent.includes('성호를 긋는다'));assert.ok(!roles(b51).filter(n=>n.attrs['data-speech-role']==='assembly').some(n=>n.textContent.includes('성호를 긋는다')));const underline51=walk(priest51).find(n=>n.classList.contains('reader__bow-phrase'));assert.equal(underline51.textContent,'성부와 + 성자와 성령');mode.value='regular';const regular51=run("renderBlock(flowBlocks(3).find(b=>b.item?.title==='강복'))");assert.ok(!regular51.textContent.includes('성호를 긋는다'));assert.ok(walk(regular51).some(n=>n.classList.contains('reader__bow-phrase')));console.log('PASS v51 blessing guidance inside priest card, exact underlined phrase and mode handling.');\n''';Path('work/test-reader-v51.cjs').write_text(t,encoding='utf-8')
